def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", resp)  # tolerate v1 shape if ever returned
    outcome = result.get("outcome") or result.get("decision")
    limit = result.get("credit_limit", result.get("limit", 0))

    if outcome in ("approved", "approve"):
        action = "issue"
    elif outcome in ("declined", "decline"):
        action = "decline"
    else:  # manual_review / refer
        action = "queue_review"

    # Network referral rule: self_employed with requested_limit > 6000
    # must go to manual review instead of being issued. A decline stays a decline.
    if action == "issue":
        employment = app.get("employment")
        requested = app.get("requested_limit", 0)
        if employment == "self_employed" and requested > 6000:
            action = "queue_review"

    if action == "issue":
        return {"action": "issue", "limit": int(limit)}
    return {"action": action, "limit": 0}
